#include <memory>
#include <string>
#include <vector>

class Animal
{
public:
    virtual ~Animal() = default;
    virtual std::string speak() const { return "..."; }
};

class Dog : public Animal { public: std::string speak() const override { return "Woof"; } };
class Cat : public Animal { public: std::string speak() const override { return "Meow"; } };

std::string chorus(const std::vector<Animal>& animals)
{
    std::string result{};
    for (const Animal& animal : animals)
    {
        if (!result.empty()) result += ' ';
        result += animal.speak();
    }
    return result;
}

solution.solution.cpp:
#include <memory>
#include <string>
#include <vector>

class Animal
{
public:
    virtual ~Animal() = default;
    virtual std::string speak() const { return "..."; }
};

class Dog : public Animal { public: std::string speak() const override { return "Woof"; } };
class Cat : public Animal { public: std::string speak() const override { return "Meow"; } };

std::string chorus(const std::vector<std::unique_ptr<Animal>>& animals)
{
    std::string result{};
    for (const auto& animal : animals)
    {
        if (!result.empty()) result += ' ';
        result += animal->speak();
    }
    return result;
}

unitTests:
TEST("every animal keeps its own voice") {
    std::vector<std::unique_ptr<Animal>> zoo;
    zoo.push_back(std::make_unique<Dog>());
    zoo.push_back(std::make_unique<Dog>());
    zoo.push_back(std::make_unique<Cat>());
    CHECK_EQ(chorus(zoo), "Woof Woof Meow");
}
TEST("an empty zoo is silent") { CHECK_EQ(chorus(std::vector<std::unique_ptr<Animal>>{}), ""); }

